fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
    let this = Pin::into_inner(self);

    loop {
        match ready!(this.pidfd.poll_read_ready(cx)) {
            Err(err) if is_rt_shutdown_err(&err) => {
                this.pidfd.reregister(Interest::READABLE)?;
                ready!(this.pidfd.poll_read_ready(cx))?
            }
            res => res?,
        }

        if let Some(status) = this.inner.try_wait()? {
            return Poll::Ready(Ok(status));
        }
        // Spurious readiness: the process has not exited yet, so poll again
        // so that a waker is registered (or retry if the fd is ready).
    }
}

